package com.hrm.service;
import java.security.Principal;import java.time.LocalDate;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class HeadRequestWorkspaceTest {
 JdbcTemplate db;PersonnelAccessService access;PersonnelWorkflowSupport support;RequestApprovalStages stages;Principal head=()->"head";
 @BeforeEach void setup(){db=mock(JdbcTemplate.class);access=mock(PersonnelAccessService.class);support=mock(PersonnelWorkflowSupport.class);stages=spy(new RequestApprovalStages(db,access,support));when(access.actor(head)).thenReturn(new PersonnelAccessService.Actor(5,50,"EMPLOYEE"));when(support.today()).thenReturn(LocalDate.of(2026,11,8));doReturn(true).when(stages).enabled();doReturn(List.of(10L)).when(stages).departments(50);}
 @Test void rejectsInvalidFiltersAndMissingTenure(){assertEquals(400,assertThrows(ResponseStatusException.class,()->stages.search(head,"INVALID",null,null,"",null,null,0,10)).getStatusCode().value());assertEquals(400,assertThrows(ResponseStatusException.class,()->stages.search(head,null,null,null,"",LocalDate.of(2026,11,9),LocalDate.of(2026,11,8),0,10)).getStatusCode().value());doReturn(List.of()).when(stages).departments(50);assertEquals(403,assertThrows(ResponseStatusException.class,()->stages.search(head,null,null,null,"",null,null,0,10)).getStatusCode().value());}
 @Test void historyOutsideDepartmentIsDenied(){when(db.queryForList(contains("SELECT employee_id FROM dbo.employee_requests"),eq(Long.class),eq(4L))).thenReturn(List.of(70L));doReturn(false).when(stages).canRead(70,head);assertEquals(403,assertThrows(ResponseStatusException.class,()->stages.history(4,head)).getStatusCode().value());verify(db,never()).queryForList(contains("audit_logs"),any(Object[].class));}
 @Test void decisionWritesBeforeAndAfterAudit(){when(db.queryForList(contains("WITH(UPDLOCK,HOLDLOCK)"),eq(4L))).thenReturn(List.of(Map.of("employee_id",70L,"status","CHO_DUYET")));doReturn(true).when(stages).canRead(70,head);when(db.queryForObject(contains("employee_request_withdrawals"),eq(Long.class),eq(4L))).thenReturn(0L);when(db.queryForList(contains("SELECT department_id FROM dbo.employee_assignments"),eq(Long.class),eq(70L),any(),any())).thenReturn(List.of(10L));var before=Map.<String,Object>of("stageStatus","PENDING");var after=Map.<String,Object>of("stageStatus","APPROVED");doReturn(before,after).when(stages).stage(4);stages.decide(4,true,"Đồng ý",head);verify(support).audit(5L,"REQUEST_HEAD_APPROVE","employee_requests",4,"Đồng ý",before,after);}
 @Test void selfApprovalStillDenied(){when(db.queryForList(contains("WITH(UPDLOCK,HOLDLOCK)"),eq(4L))).thenReturn(List.of(Map.of("employee_id",50L,"status","CHO_DUYET")));assertEquals(403,assertThrows(ResponseStatusException.class,()->stages.decide(4,true,"",head)).getStatusCode().value());verify(support,never()).audit(any(),anyString(),anyString(),anyLong(),any(),any(),any());}
}
